# Natural Earth public-domain land, identical to Android maps/land.json.
# Embedded to preserve the standalone Linux archive's six-file contract.
LAND_ZLIB_BASE64 = ''

class RouteMap(Gtk.DrawingArea):
    """Offline world stippling matching Android beta25; no inferred location."""
    def __init__(self):
        super().__init__()
        self.set_content_height(200);self.set_hexpand(True)
        self.set_tooltip_text('Карта мира / World map')
        self.layer=None;self.layer_key=None;self.tick=0;self.phase=0
        self.set_draw_func(self.draw_map)
        self.connect('map',self.start_motion);self.connect('unmap',self.stop_motion)
    def start_motion(self,*_):
        if not self.tick and self.get_settings().get_property('gtk-enable-animations'):
            self.tick=self.add_tick_callback(self.animate)
    def stop_motion(self,*_):
        if self.tick:self.remove_tick_callback(self.tick);self.tick=0
    def animate(self,widget,clock):
        if not self.get_settings().get_property('gtk-enable-animations'):
            self.phase=0;self.tick=0;self.queue_draw();return False
        self.phase=clock.get_frame_time()/5200000%1;self.queue_draw();return True
    @staticmethod
    def land_layer(width,height,scale):
        import cairo,json,zlib,math
        w=max(1,round(width*scale));h=max(1,round(height*scale))
        mask=cairo.ImageSurface(cairo.FORMAT_ARGB32,w,h);cr=cairo.Context(mask)
        for ring in json.loads(zlib.decompress(base64.b64decode(LAND_ZLIB_BASE64))):
            for i,(lon,lat) in enumerate(ring):
                (cr.move_to if i==0 else cr.line_to)((lon+180)/360*w,(85-lat)/145*h)
            cr.close_path()
        cr.set_fill_rule(cairo.FILL_RULE_EVEN_ODD);cr.set_source_rgba(1,1,1,1);cr.fill();mask.flush()
        data=mask.get_data();stride=mask.get_stride()
        layer=cairo.ImageSurface(cairo.FORMAT_ARGB32,w,h);cr=cairo.Context(layer)
        cr.set_source_rgb(152/255,247/255,216/255)
        diameter=max(1,math.floor(.65*scale+.5));offset=.5 if diameter%2 else 0
        spacing=2.3*scale;row_spacing=spacing*.8660254
        for row in range(math.ceil(h/row_spacing)):
            y=math.floor(row*row_spacing-offset+.5)+offset
            for col in range(math.ceil(w/spacing)):
                x=math.floor((col+.5*(row%2))*spacing-offset+.5)+offset
                if 0<=x<w and 0<=y<h and data[int(y)*stride+int(x)*4+3]>=128:
                    cr.new_sub_path();cr.arc(x,y,diameter/2,0,2*math.pi)
        cr.fill();layer.flush();return layer
    def draw_map(self,widget,cr,width,height):
        import math
        scale=self.get_scale_factor();key=(width,height,scale)
        if key!=self.layer_key:self.layer=self.land_layer(*key);self.layer_key=key
        cr.save();cr.rectangle(0,0,width,height);cr.clip()
        cr.set_source_rgb(3/255,17/255,14/255);cr.paint()
        cr.set_source_rgba(70/255,139/255,117/255,45/255);cr.set_line_width(.4)
        for x in range(0,width,16):cr.move_to(x,0);cr.line_to(x,height)
        for y in range(0,height,16):cr.move_to(0,y);cr.line_to(width,y)
        cr.stroke();cr.save();cr.scale(1/scale,1/scale);cr.set_source_surface(self.layer)
        cr.paint_with_alpha((120+6*math.sin(2*math.pi*self.phase))/255);cr.restore()
        cr.set_source_rgb(70/255,139/255,117/255);cr.set_line_width(1)
        cr.rectangle(.5,.5,max(0,width-1),max(0,height-1));cr.stroke();cr.restore()

